{"source":"def investigate(context, acquire):
    rows = []
    sequence = 0
    open_transaction = False
    saved_rows = []
    saved_sequence = 0
    for action in context['actions']:
        op = action['op']
        if op == 'put':
            ident = action['id']
            rows.append(ident)
            if ident > sequence:
                sequence = ident
        elif op == 'delete':
            ident = action['id']
            if ident in rows:
                rows.remove(ident)
        elif op == 'begin':
            open_transaction = True
            saved_rows = list(rows)
            saved_sequence = sequence
        elif op == 'commit':
            open_transaction = False
        elif op == 'rollback':
            open_transaction = False
            rows = list(saved_rows)
            sequence = saved_sequence
    return sequence + 1
